PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE schema_migrations (
  version INTEGER PRIMARY KEY,
  applied_at TEXT NOT NULL
);
CREATE TABLE settings (            -- per-repo DB, so per-repo enforcement mode lives here
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
, updated_at TEXT);
CREATE TABLE repos (
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'repo-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  slug TEXT NOT NULL UNIQUE CHECK (length(trim(slug)) > 0)
, updated_at TEXT);
CREATE TABLE issue_refs (          -- normalized issue reference: real URL XOR placeholder
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'ref-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  url TEXT UNIQUE CHECK (url IS NULL OR url GLOB 'https://github.com/*/issues/*'),
  temp_id TEXT UNIQUE CHECK (temp_id IS NULL OR
    temp_id GLOB 'TMP-[A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9]' OR
    temp_id GLOB 'MIG-[A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9]'),  -- MIG-: import-only (CLI-enforced)
  created_at TEXT NOT NULL, updated_at TEXT,
  CHECK ((url IS NULL) != (temp_id IS NULL))   -- exactly one
);
CREATE TABLE marathons (
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'mar-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  repo_id INTEGER NOT NULL REFERENCES repos(id),
  tracking_ref_id INTEGER NOT NULL REFERENCES issue_refs(id),
  status TEXT NOT NULL CHECK (status IN ('planned','running','done','escalated','abandoned')),
  created_at TEXT NOT NULL
, updated_at TEXT);
CREATE TABLE releases (
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'rel-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  repo_id INTEGER NOT NULL REFERENCES repos(id),
  version TEXT CHECK (version IS NULL OR length(trim(version)) > 0),
  codename TEXT,
  status TEXT NOT NULL CHECK (status IN ('draft','active','shipped','cut')),
  target_date TEXT CHECK (target_date IS NULL OR target_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  shipped_date TEXT CHECK (shipped_date IS NULL OR shipped_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  description TEXT NOT NULL CHECK (length(trim(description)) > 0),
  exit_criterion TEXT,
  tracking_ref_id INTEGER NOT NULL REFERENCES issue_refs(id),
  marathon_id INTEGER REFERENCES marathons(id),
  gh_release_url TEXT,
  milestone TEXT,
  front_door_reviewed TEXT CHECK (front_door_reviewed IN ('Yes','No') OR front_door_reviewed IS NULL),
  shakedown_reviewed  TEXT CHECK (shakedown_reviewed  IN ('Yes','No') OR shakedown_reviewed  IS NULL),
  license_file        TEXT CHECK (license_file        IN ('Yes','No') OR license_file        IS NULL), baseline_count INTEGER, baseline_at TEXT, baseline_source TEXT CHECK (baseline_source IS NULL OR baseline_source IN ('observed','backfilled')), updated_at TEXT,
  UNIQUE (repo_id, version)
);
CREATE TABLE doc_lines (               -- document-level verbatim preservation (r2: the 86-line
  id INTEGER PRIMARY KEY,              -- preamble is release-less; legacy_lines can't hold it)
  repo_id INTEGER NOT NULL REFERENCES repos(id),
  position INTEGER NOT NULL,           -- ordering among document-level segments
  content TEXT NOT NULL, updated_at TEXT,
  UNIQUE (repo_id, position)
);
CREATE TABLE legacy_lines (            -- lossless import: unmapped/continuation lines, verbatim
  id INTEGER PRIMARY KEY,
  release_id INTEGER NOT NULL REFERENCES releases(id),
  position INTEGER NOT NULL,
  content TEXT NOT NULL,
  disposition TEXT, updated_at TEXT,                    -- NULL = pending; else 'kept'|'migrated'|'dropped:<why>'
  UNIQUE (release_id, position)
);
CREATE TABLE grandfather_entries (     -- r3: referenced throughout but previously never defined
  id INTEGER PRIMARY KEY,
  import_run TEXT NOT NULL,            -- one id per `releases import` invocation
  release_gid TEXT,                    -- NULL for document-level entries
  rule TEXT NOT NULL,                  -- which rule was tolerated/defaulted
  source_value TEXT,                   -- what the legacy file had (NULL = field absent)
  supplied_value TEXT,                 -- what import wrote (default, MIG- ref, normalization)
  disposition TEXT                     -- NULL = pending; strict flip requires none pending
, updated_at TEXT);
CREATE TABLE op_receipts (             -- append-only CLI operation log (append-only via the same
  id INTEGER PRIMARY KEY,              -- trigger pair as manifest_state_events)
  op TEXT NOT NULL,
  target_gid TEXT,
  at TEXT NOT NULL,
  txn_id TEXT NOT NULL,                -- one per CLI transaction
  session_id TEXT NOT NULL,            -- r3: stable per-dogfood-session id (env-provided), so the
                                       --   exit gate's ">=2 sessions" is mechanically checkable
  state_digest_before TEXT NOT NULL,   -- sha256 of the BUSINESS-STATE dump (r3: excludes
  state_digest_after TEXT NOT NULL     --   op_receipts, lock_audit, generation, and all digest
);
CREATE TABLE roadmap_items (  -- GH-69/GH-269: roadmap ledger.
  id INTEGER PRIMARY KEY,                   --
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'rmi-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'), -- edit; `releases roadmap sync` mirrors it here. Rows
  repo_id INTEGER NOT NULL REFERENCES repos(id),  -- follow the GH-32 grammar (GID-keyed, no
  gh_number INTEGER,                        -- integer ids as dump values), so merges and rebuilds
  title TEXT NOT NULL CHECK (length(trim(title)) > 0),  -- need nothing new.
  section TEXT NOT NULL CHECK (length(trim(section)) > 0),
  position INTEGER NOT NULL,                -- order within its section at last sync
  status_marker TEXT,                       -- the entry's leading status emoji, when present
  complexity INTEGER, risk INTEGER, effort INTEGER,     -- cx/risk/eff when the entry states them
  doc_path TEXT,                            -- first PROJECT/** link
  issue_url TEXT,                           -- first this-repo issue/PR URL
  raw_text TEXT NOT NULL,                   -- the entry block VERBATIM (lossless shadow)
  first_seen TEXT NOT NULL,
  updated_at TEXT NOT NULL, rating_pri INTEGER CHECK (rating_pri IS NULL OR (rating_pri BETWEEN 1 AND 100)), rating_sev INTEGER CHECK (rating_sev IS NULL OR (rating_sev BETWEEN 1 AND 100)), rating_appeal INTEGER CHECK (rating_appeal IS NULL OR (rating_appeal BETWEEN 1 AND 100)), rating_effort INTEGER CHECK (rating_effort IS NULL OR (rating_effort BETWEEN 1 AND 100)), rating_ovr INTEGER CHECK (rating_ovr IS NULL OR (rating_ovr BETWEEN 4 AND 400)), status_label TEXT CHECK(status_label IS NULL OR status_label = 'in-progress'),                 -- last sync that CHANGED this row (not last sync run)
  UNIQUE (repo_id, gh_number)
);
CREATE TABLE IF NOT EXISTS "manifest_items" (
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'mfi-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  release_id INTEGER NOT NULL REFERENCES releases(id),
  issue_ref_id INTEGER NOT NULL REFERENCES issue_refs(id),
  state TEXT NOT NULL CHECK (state IN ('dialed_in','shipped','cut')),
  dialed_in_at TEXT,
  dial_reason TEXT,
  marathon_id INTEGER REFERENCES marathons(id)
, updated_at TEXT);
CREATE TABLE IF NOT EXISTS "manifest_state_events" (
  id INTEGER PRIMARY KEY,
  item_id INTEGER NOT NULL REFERENCES manifest_items(id),
  from_state TEXT NOT NULL CHECK (from_state IN ('open','dialed_in','shipped','cut')),
  to_state   TEXT NOT NULL CHECK (to_state   IN ('open','dialed_in','shipped','cut')),
  at TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (length(trim(reason)) > 0)
);
CREATE TABLE jog_queue (
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'jog-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  repo_id INTEGER NOT NULL REFERENCES repos(id),
  gh_number INTEGER NOT NULL,
  position INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'completed', 'parked', 'failed', 'dropped', 'archived')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  lease_pid INTEGER,
  failure_reason TEXT,
  UNIQUE (repo_id, gh_number)
);
CREATE TABLE work_events (
  id INTEGER PRIMARY KEY,
  global_id TEXT NOT NULL UNIQUE CHECK (global_id GLOB 'wev-[0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z][0-9A-HJKMNP-TV-Z]'),
  repo_id INTEGER NOT NULL REFERENCES repos(id),
  gh_number INTEGER,
  txn_id TEXT NOT NULL,
  event TEXT NOT NULL,
  payload TEXT,
  at TEXT NOT NULL
);
CREATE TABLE connector_cursors (
  connector TEXT PRIMARY KEY,
  last_event_id INTEGER NOT NULL DEFAULT 0,
  last_attempt_at TEXT,
  last_error TEXT,
  updated_at TEXT NOT NULL
);
CREATE TRIGGER op_no_update BEFORE UPDATE ON op_receipts
  BEGIN SELECT RAISE(ABORT, 'op_receipts is append-only'); END;
CREATE TRIGGER op_no_delete BEFORE DELETE ON op_receipts
  BEGIN SELECT RAISE(ABORT, 'op_receipts is append-only'); END;
CREATE INDEX idx_releases_repo ON releases(repo_id);
CREATE INDEX idx_legacy_release ON legacy_lines(release_id);
CREATE INDEX idx_gf_import ON grandfather_entries(import_run);
CREATE INDEX idx_roadmap_repo ON roadmap_items(repo_id);
CREATE UNIQUE INDEX idx_mfi_active_exclusive
                      ON manifest_items(issue_ref_id) WHERE state = 'dialed_in';
CREATE INDEX idx_mfi_release ON manifest_items(release_id);
CREATE TRIGGER mse_no_update BEFORE UPDATE ON manifest_state_events
                      BEGIN SELECT RAISE(ABORT, 'manifest_state_events is append-only'); END;
CREATE TRIGGER mse_no_delete BEFORE DELETE ON manifest_state_events
                      BEGIN SELECT RAISE(ABORT, 'manifest_state_events is append-only'); END;
CREATE INDEX idx_mse_item ON manifest_state_events(item_id);
CREATE UNIQUE INDEX idx_rel_marathon_exclusive
                      ON releases(marathon_id) WHERE marathon_id IS NOT NULL;
CREATE TRIGGER rel_baseline_shape_ins BEFORE INSERT ON releases WHEN (NEW.baseline_count IS NULL) + (NEW.baseline_at IS NULL) + (NEW.baseline_source IS NULL) NOT IN (0, 3) BEGIN SELECT RAISE(ABORT, 'releases baseline fields are all-NULL or all-populated'); END;
CREATE TRIGGER rel_baseline_shape_upd BEFORE UPDATE ON releases WHEN (NEW.baseline_count IS NULL) + (NEW.baseline_at IS NULL) + (NEW.baseline_source IS NULL) NOT IN (0, 3) BEGIN SELECT RAISE(ABORT, 'releases baseline fields are all-NULL or all-populated'); END;
CREATE TRIGGER rel_baseline_write_once BEFORE UPDATE OF baseline_count
                      ON releases
                      WHEN OLD.baseline_count IS NOT NULL
                       AND NEW.baseline_count IS NOT OLD.baseline_count
                      BEGIN SELECT RAISE(ABORT, 'releases.baseline_count is write-once'); END;
CREATE TRIGGER rel_baseline_at_write_once BEFORE UPDATE OF baseline_at ON releases
                          WHEN OLD.baseline_at IS NOT NULL AND NEW.baseline_at IS NOT OLD.baseline_at
                          BEGIN SELECT RAISE(ABORT,
                            'releases.baseline_at is write-once (baseline provenance)'); END;
CREATE TRIGGER rel_baseline_source_write_once BEFORE UPDATE OF baseline_source ON releases
                          WHEN OLD.baseline_source IS NOT NULL AND NEW.baseline_source IS NOT OLD.baseline_source
                          BEGIN SELECT RAISE(ABORT,
                            'releases.baseline_source is write-once (baseline provenance)'); END;
CREATE INDEX idx_jog_queue_repo_pos ON jog_queue(repo_id, position);
CREATE INDEX idx_jog_queue_status ON jog_queue(status);
CREATE INDEX idx_work_events_gh ON work_events(gh_number);
CREATE TRIGGER work_events_no_update BEFORE UPDATE ON work_events
                          BEGIN SELECT RAISE(ABORT, 'work_events is append-only'); END;
CREATE TRIGGER work_events_no_delete BEFORE DELETE ON work_events
                          BEGIN SELECT RAISE(ABORT, 'work_events is append-only'); END;
COMMIT;
